'use strict';
const fs=require('fs');
const vtracer=require('@visioncortex/vtracer');
const earcut=require('earcut').default;

// Input is generated by our decoder. Accept only VTracer's geometry, never
// scripts, styles, URLs or external resources. Flatten fitted cubic curves
// adaptively at subpixel tolerance for the game's 16-vertex polygon format.
function flattenCubic(a,b,c,d,out,depth=0){
 const distance=p=>{const dx=d[0]-a[0],dy=d[1]-a[1],length=Math.hypot(dx,dy);return length?Math.abs(dy*p[0]-dx*p[1]+d[0]*a[1]-d[1]*a[0])/length:Math.hypot(p[0]-a[0],p[1]-a[1]);};
 if(depth>=12||Math.max(distance(b),distance(c))<=.3){out.push(d);return;}
 const mid=(p,q)=>[(p[0]+q[0])/2,(p[1]+q[1])/2];
 const ab=mid(a,b),bc=mid(b,c),cd=mid(c,d),abc=mid(ab,bc),bcd=mid(bc,cd),center=mid(abc,bcd);
 flattenCubic(a,ab,abc,center,out,depth+1);flattenCubic(center,bcd,cd,d,out,depth+1);
}
function rings(d){
 const tokens=d.match(/[a-zA-Z]|[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:e[-+]?\d+)?/g)||[];
 const out=[];let i=0,cmd='',x=0,y=0,start=null,points=[];
 function finish(){if(points.length>2)out.push(points);points=[];start=null;}
 while(i<tokens.length){
  if(/^[a-z]$/i.test(tokens[i]))cmd=tokens[i++];
  const rel=cmd===cmd.toLowerCase();
  if(cmd.toUpperCase()==='Z'){if(start){x=start[0];y=start[1];}finish();cmd='';continue;}
  if(cmd.toUpperCase()==='C'){
   const values=tokens.slice(i,i+6).map(Number);i+=6;
   if(values.length!==6||!values.every(Number.isFinite))throw Error('Invalid traced curve');
   const point=n=>[values[n]+(rel?x:0),values[n+1]+(rel?y:0)];
   const end=point(4);flattenCubic([x,y],point(0),point(2),end,points);[x,y]=end;continue;
  }
  if(!['M','L','H','V'].includes(cmd.toUpperCase()))throw Error('Unsupported traced path command');
  let nx=x,ny=y;
  if(cmd.toUpperCase()==='H')nx=Number(tokens[i++])+(rel?x:0);
  else if(cmd.toUpperCase()==='V')ny=Number(tokens[i++])+(rel?y:0);
  else{nx=Number(tokens[i++])+(rel?x:0);ny=Number(tokens[i++])+(rel?y:0);}
  if(!Number.isFinite(nx+ny))throw Error('Invalid traced coordinate');
  if(cmd.toUpperCase()==='M'){finish();start=[nx,ny];cmd=rel?'l':'L';}
  x=nx;y=ny;points.push([x,y]);
 }
 finish();return out;
}
const key=p=>p[0]+','+p[1];
function clean(points){return points.filter((p,i)=>key(p)!==key(points[(i+1)%points.length])).filter((p,i,a)=>{
 const prev=a[(i+a.length-1)%a.length],next=a[(i+1)%a.length];return Math.abs((p[0]-prev[0])*(next[1]-p[1])-(p[1]-prev[1])*(next[0]-p[0]))>1e-8;
});}
function polygons(paths){
 // VTracer stacked paths normally contain a single outer ring. Earcut also
 // preserves actual inner rings, so transparent holes are not painted solid.
 const flat=[],holes=[];for(let r=0;r<paths.length;r++){if(r)holes.push(flat.length/2);for(const p of paths[r])flat.push(...p);}
 if(paths.length===1&&paths[0].length<=16)return [paths[0]];
 const tris=earcut(flat,holes,2);let polys=[];
 for(let i=0;i<tris.length;i+=3)polys.push(tris.slice(i,i+3).map(j=>[flat[j*2],flat[j*2+1]]));
 // Merge neighboring triangles into concave polygons, keeping the game's
 // 16-vertex cap. Shared-edge removal preserves the whole traced region.
 for(let pass=0;pass<12;pass++){
  let changed=false;const edges=new Map();
  outer:for(let i=0;i<polys.length;i++){
   const a=polys[i];if(!a)continue;
   for(let u=0;u<a.length;u++){
    const edge=key(a[u])+'|'+key(a[(u+1)%a.length]);const reverse=key(a[(u+1)%a.length])+'|'+key(a[u]);
    const match=edges.get(reverse);
    if(match){const [j,v]=match,b=polys[j];if(!b)continue;
     const merged=[];for(let n=1;n<=a.length;n++)merged.push(a[(u+n)%a.length]);for(let n=2;n<b.length;n++)merged.push(b[(v+n)%b.length]);
     const simple=clean(merged);
     if(simple.length>=3&&simple.length<=16){polys[i]=simple;polys[j]=null;changed=true;break outer;}
    }
    edges.set(edge,[i,u]);
   }
  }
  polys=polys.filter(Boolean);if(!changed)break;
  // Continue enough times to absorb long outlines, with a finite work bound.
  if(pass===11&&polys.length>2&&polys.length<3000)pass=-1;
 }
 return polys;
}
function contourPolygons(all){
 const area=p=>Math.abs(p.reduce((a,v,i)=>{const n=p[(i+1)%p.length];return a+v[0]*n[1]-n[0]*v[1];},0));
 const inside=(point,p)=>{let yes=false;for(let i=0,j=p.length-1;i<p.length;j=i++){const a=p[i],b=p[j];if((a[1]>point[1])!==(b[1]>point[1])&&point[0]<(b[0]-a[0])*(point[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes;}return yes;};
 const nodes=all.map(p=>({p,area:area(p),parent:-1,depth:0}));
 for(let i=0;i<nodes.length;i++){
  let best=Infinity;for(let j=0;j<nodes.length;j++)if(nodes[j].area>nodes[i].area&&nodes[j].area<best&&inside(nodes[i].p[0],nodes[j].p)){nodes[i].parent=j;best=nodes[j].area;}
 }
 for(const n of nodes){let at=n.parent;while(at>=0){n.depth++;at=nodes[at].parent;}}
 const out=[];
 for(let i=0;i<nodes.length;i++)if(nodes[i].depth%2===0)out.push(...polygons([nodes[i].p,...nodes.filter(n=>n.parent===i&&n.depth%2===1).map(n=>n.p)]));
 return out;
}
const req=JSON.parse(fs.readFileSync(0,'utf8'));
const svg=vtracer.convertBuffer(Buffer.from(req.png,'base64'),{mode:req.mode==='spline'?'spline':'polygon',hierarchical:'stacked',maxColors:req.colors,colorPrecision:8,filterSpeckle:req.speckle||0,simplify:req.simplify??0.5,cornerThreshold:req.cornerThreshold??80,pathPrecision:3,optimize:1});
const shapes=[],regions=[];
for(const m of svg.matchAll(/<path\b([^>]+)\/?\s*>/g)){
 const d=/\bd="([^"]+)"/.exec(m[1]),fill=/\bfill="(#[0-9a-fA-F]{6})"/.exec(m[1]);if(!d||!fill)continue;
 const transform=/\btransform="translate\(([-0-9.]+)[ ,]([-0-9.]+)\)"/.exec(m[1]);
 const offset=transform?[+transform[1],+transform[2]]:[0,0];
 const paths=rings(d[1]).map(points=>points.map(p=>[p[0]+offset[0],p[1]+offset[1]]));
 const parts=contourPolygons(paths).map(points=>({t:'polygon',points,fill:fill[1].toLowerCase()}));
 regions.push({paths,shapes:parts,fill:fill[1].toLowerCase()});shapes.push(...parts);
}
process.stdout.write(JSON.stringify({shapes,regions}));
